DeleteQueue edited other queues' attributes field by field and ran an
expiry sweep on the queue it was about to remove. The unlink is now a
Queue method and the lookup is the removal itself." -m "Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"
python3 - <<'EOF'
def sub(path,a,b):
    s=open(path).read(); assert a in s,a; open(path,'w').write(s.replace(a,b))
sub('src/queue.rs','''        let retention = self.attributes.retention_seconds;
        let is_expired = |m: &Message| now >= m.sent_at + retention;
        if !self.oldest_sent_at.is_some_and(|t| now >= t + retention) {
            return;
        }
        let expired: Vec<ArrivalKey> = self
            .messages
            .iter()
            .filter(|(_, m)| is_expired(m))''','''        let retention = self.attributes.retention_seconds;
